package pack
import("context";"database/sql";_ "embed";"fmt";"github.com/ynw0/airgap-mirror/internal/domain")
//go:embed manifest_schema.sql
var manifestSchema string
func InitManifest(ctx context.Context,db *sql.DB)error{_,e:=db.ExecContext(ctx,manifestSchema);if e!=nil{return fmt.Errorf("init manifest: %w",e)};return nil};func PutManifestMeta(ctx context.Context,db *sql.DB,k,v string)error{_,e:=db.ExecContext(ctx,`INSERT INTO manifest_meta(key,value)VALUES(?,?)`,k,v);return e};func PutPublishUnit(ctx context.Context,db *sql.DB,u domain.PublishUnit)error{_,e:=db.ExecContext(ctx,`INSERT INTO publish_units(id,epoch_id,source_id,unit_key,required_count,metadata_path)VALUES(?,?,?,?,?,?)`,u.ID,u.EpochID,u.SourceID,u.Key,u.Required,u.MetadataPath);return e};func PutManifestEntry(ctx context.Context,db *sql.DB,m domain.ManifestEntry)error{a:=m.Artifact;_,e:=db.ExecContext(ctx,`INSERT INTO entries(entry_id,pack_id,pack_offset,record_length,source_id,epoch_id,logical_path,size,sha256,operation,publish_unit_id,package_key,version,metadata,attributes)VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)`,m.EntryID,m.PackID,m.PackOffset,m.RecordLength,a.SourceID,a.EpochID,a.LogicalPath,a.Size,a.SHA256,a.Operation,a.PublishUnitID,a.PackageKey,a.Version,a.Metadata,[]byte(a.Attributes));return e}
